import React, { createContext, useState } from 'react';
import FormGroup from './FormGroup';
import formData from './formData';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [formData, setFormData] = useState(formData);
  const [submissionStatus, setSubmissionStatus] = useState(null);

  const handleInputChange = (event) => {
    setFormData({
      ...formData,
      [event.target.name]: event.target.value,
    });
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    setSubmissionStatus({ submitted: true });
  };

  return (
    <FeedbackContext.Provider value={{ formData, setFormData, submissionStatus, setSubmissionStatus }}>
      {children}
    </FeedbackContext.Provider>
  );
};

const FeedbackForm = () => {
  const { formData, setFormData, submissionStatus } = useContext(FeedbackContext);

  return (
    <form onSubmit={handleSubmit}>
      {Object.keys(formData).map((question, index) => (
        <FormGroup
          key={index}
          question={question}
          value={formData[question]}
          onChange={handleInputChange}
        />
      ))}
      {submissionStatus === { submitted: true } && (
        <p>Thanks for your feedback!</p>
      )}
    </form>
  );
};

const App = () => {
