    let canvasHeight = canvas.getHeight();
    let pendulumLength = 200;

    function update() {
      acceleration = -(gravitationalConstant / pendulumLength) * Math.sin(Math.radians(angle));
      velocity += acceleration;
      angle += velocity;

      if (angle > 0) {
        angle = 0;
      }
      if (angle < -180) {
        angle = -180;
      }
