      canvas.clearRect(0, 0, canvasWidth, canvasHeight);
      ctx.beginPath();
      ctx.strokeStyle = "black";
      ctx.lineCap = "round";
      ctx.lineWidth = 2;
      ctx.moveTo(canvasWidth / 2, canvasHeight / 2);
      ctx.lineTo(canvasWidth / 2 + pendulumLength * Math.sin(Math.radians(angle)), canvasHeight / 2 - pendulumLength * Math.cos(Math.radians(angle)));
